corporate_design.toad_component_blueprint:
canvas {
  size: 900px 560px;
  fill: #FFFFFF;
  font-family: "Arial, sans-serif";
}

>navy = #1E3A8A;

rect #ozgCard {
  at: center of canvas;
  size: 800px 460px;
  fill: #F8FAFC;
  stroke: #CBD5E1;
  stroke-width: 1px;
  radius: 8px;
}

text #ozgHeader {
  at: top left of #ozgCard offset 36px 36px;
  content: "KREISVERWALTUNG // DIGITALES BÜRGERPORTAL";
  font-size: 13px;
  font-weight: 700;
  color: >navy;
}

text #ozgTitle {
  at: below #ozgHeader offset 14px;
  content: "Wohnsitz ummelden & Reisepass beantragen – 100% online";
  font-size: 26px;
  font-weight: 700;
  color: #0F172A;
}
